using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class WavyCanalCheck{static WavyCanalCheck(){EditorApplication.update+=Poll;}static string Key(Vector3 p)=>Mathf.RoundToInt(p.x*1000)+","+Mathf.RoundToInt(p.y*1000)+","+Mathf.RoundToInt(p.z*1000);static void Poll(){if(EditorApplication.isCompiling||!File.Exists("WavyCanalCheck.request"))return;File.Delete("WavyCanalCheck.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var f=s.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(m=>m.name=="Canal1");var old=AssetDatabase.LoadAssetAtPath<Mesh>(File.ReadAllText("FinalEnvironmentRoadBackup/BeforeWavyCanal/Original Mesh.txt"));var have=new HashSet<string>(f.sharedMesh.vertices.Select(f.transform.TransformPoint).Select(Key));int missing=old.triangles.Distinct().Select(i=>f.transform.TransformPoint(old.vertices[i])).Where(p=>p.y>=27.7f).Count(p=>!Enumerable.Range(-1,3).Any(x=>Enumerable.Range(-1,3).Any(y=>Enumerable.Range(-1,3).Any(z=>have.Contains(Key(p+new Vector3(x,y,z)*.001f))))));var newPoints=f.sharedMesh.vertices.Select(f.transform.TransformPoint).ToArray();var distances=old.triangles.Distinct().Select(i=>f.transform.TransformPoint(old.vertices[i])).Where(p=>p.y>=27.7f&&!have.Contains(Key(p))).Select(p=>newPoints.Min(q=>(p-q).sqrMagnitude)).ToArray();File.AppendAllText("FinalEnvironmentRoadReview/WavyCanalBanks.txt","\nExact nearest-coordinate maximum difference="+Mathf.Sqrt(distances.Length>0?distances.Max():0)+"m");typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,new Vector3(240,640,-175),new Vector3(240,25,-175),"Wavy-Canal-Banks-Closeup"});File.AppendAllText("FinalEnvironmentRoadReview/WavyCanalBanks.txt","\nCHECK road/promenade height original vertices missing="+missing+"; material slots="+f.GetComponent<MeshRenderer>().sharedMaterials.Length+"; submeshes="+f.sharedMesh.subMeshCount);}}


